# PURPOSE: react to controller key presses in a build mode prototype
class Event:
    def __init__(self, key):
        self.key = key

x = 100
health = 100
press = Event("d")
print("Key:", press.key)

# The handler
def control(event):
    global x
    global health
    if event.key == "d":
        x = x + 15
    elif event.key == "a":
        x = x - 15
    elif event.key == "h":
        health = health - 25
    elif event.key == "m":
        health = health + 50
    elif event.key == "q":
        print("Build mode")
    else:
        print("Unknown key")

